head.script:
scwin.test = function(v, dv, row, col) {
    //alert("aa");
    log = "aa";
    return v
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행한다.
    //1. Run the sample file.
    //Verify step 1. When the "aa" value is displayed in the notification window and click OK, the second message window is displayed.
    WebSquare.wUnit.addCommand("assert", "log == 'aa'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 왼쪽상단의 전체 체크박스를 클릭한다.
    //2. Click the check box in the upper left corner.
    //Verify step 2. The notification window does not appear (previously the notification window is executed again).
    WebSquare.wUnit.addCommand("set", "log = ''");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_column9').childNodes[0].click()");
    WebSquare.wUnit.addCommand("assert", "log == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    dataList1.setJSON([{
        "col1": "1",
        "col2": "4",
        "col3": "7",
        "rowStatus": "R"
    }, {
        "col1": "2",
        "col2": "5",
        "col3": "8",
        "rowStatus": "R"
    }, {
        "col1": "3",
        "col2": "6",
        "col3": "9",
        "rowStatus": "R"
    }]);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
